<script setup lang="ts">
import {computed,onMounted,onUnmounted,toRefs,ref} from 'vue';
import {CalendarDays,Plus,ChevronLeft,ChevronRight,Check,Clock3,FileDown} from 'lucide-vue-next';
import {academicCache,schoolTerm} from '../composables/handan-academic';
import {schedule} from '../composables/schedule';
import {agendaView,taskSnapshot,tasksReady,tasksBusy,taskError,taskReminderStatus,initTasks,reloadTasks,changeTasks,enableTaskReminders} from '../composables/tasks';
import {beijingDay,validDay,shiftDay,buildAgenda,type CampusTask,type AgendaEvent,type CourseSeries} from '../domain/agenda';
import {flatten,uid} from '../domain/schedule';
import {taskStore} from '../services/task-store';
import {saveFile} from '../services/files';
import type {Course} from '../domain/academic';
const emit=defineEmits<{course:[course:Course];navigate:[section:string]}>();
const now=ref(new Date()),removeIntent=ref(''),message=ref(''),error=ref('');
const {date,range,filter,showCompleted,editor,editing}=toRefs(agendaView);
let followToday=date.value===beijingDay();
const draft=agendaView.draft;
const selectedDay=computed(()=>validDay(date.value)?date.value:beijingDay(now.value));
const series=computed<CourseSeries[]>(()=>{const all:CourseSeries[]=[];const school=schoolTerm.value?.data;if(school)all.push({semester:school.semester,courses:flatten(school.courses,school.semester.id,school.table),source:'school'});if(schedule.value.mode==='personal')for(const semester of schedule.value.semesters){const table=schedule.value.timeTables.find(t=>t.id===semester.timeTableId);all.push({semester,courses:flatten(schedule.value.courses,semester.id,table),source:'personal'})}return all});
const agenda=computed(()=>buildAgenda(series.value,academicCache.value.exams.data||[],taskSnapshot.value.tasks,selectedDay.value,range.value,now.value));
const visible=computed(()=>agenda.value.events.filter(e=>(filter.value==='all'||e.kind===filter.value)&&(showCompleted.value||!e.completed)));
const days=computed(()=>Array.from({length:range.value},(_,i)=>{const day=shiftDay(selectedDay.value,i);return {date:day,events:visible.value.filter(e=>e.date===day)}}));
const overdue=computed(()=>agenda.value.overdue.filter(t=>showCompleted.value||!t.completed));
const undated=computed(()=>agenda.value.undated.filter(t=>showCompleted.value||!t.completed));
const totalTasks=computed(()=>taskSnapshot.value.tasks.filter(t=>!t.completed).length);
const taskMap=computed(()=>new Map(taskSnapshot.value.tasks.map(t=>[t.id,t])));
function moveDay(n:number){followToday=false;date.value=shiftDay(selectedDay.value,n)}
function today(){followToday=true;date.value=beijingDay()}
function startTask(task?:CampusTask){editing.value=task?.id||'';Object.assign(draft,{title:task?.title||'',course:task?.course||'',deadline:task?.deadline||'',notes:task?.notes||'',remindMinutes:task?(task.remindMinutes??-1):30});editor.value=true;error.value='';message.value=''}
async function saveTask(){error.value='';try{const previous=taskMap.value.get(editing.value),stamp=new Date().toISOString();await changeTasks(()=>taskStore.upsert({id:editing.value||uid(),title:draft.title.trim(),course:draft.course.trim(),deadline:draft.deadline||null,notes:draft.notes.trim(),completed:previous?.completed??false,remindMinutes:draft.deadline&&draft.remindMinutes>=0?draft.remindMinutes:null,createdAt:previous?.createdAt??stamp,updatedAt:stamp}));editor.value=false;message.value='待办已保存到本机'}catch(e){error.value=(e as Error).message}}
async function complete(id:string){error.value='';try{const t=taskMap.value.get(id);if(t)await changeTasks(()=>taskStore.complete(id,!t.completed))}catch(e){error.value=(e as Error).message}}
async function removeTask(id:string){try{await changeTasks(()=>taskStore.remove(id));removeIntent.value='';message.value='待办已删除'}catch(e){error.value=(e as Error).message}}
function select(e:AgendaEvent){if(e.kind==='task'){const t=taskMap.value.get(e.taskId!);if(t)startTask(t)}else if(e.course)emit('course',e.course);else emit('navigate','exams')}
function state(e:AgendaEvent){if(e.completed)return '已完成';if(e.startAt===null)return '时间待核对';if(e.kind==='task')return e.startAt<+now.value?'已逾期':'待完成';return (e.endAt??e.startAt)<+now.value?'已结束':e.startAt<=+now.value?'进行中':'未开始'}
function dayTitle(day:string){const weekday=new Intl.DateTimeFormat('zh-CN',{weekday:'short',timeZone:'Asia/Shanghai'}).format(new Date(day+'T12:00:00+08:00'));return `${day===beijingDay(now.value)?'今天 · ':''}${day.slice(5).replace('-','月')}日 ${weekday}`}
async function exportTasks(){try{await saveFile('handan-tasks-'+beijingDay()+'.json',JSON.stringify(taskSnapshot.value,null,2));message.value='待办备份已生成'}catch{error.value='备份未完成，待办仍保存在本机'}}
async function restoreFile(e:Event){const input=e.target as HTMLInputElement,file=input.files?.[0];if(!file)return;try{if(file.size>1024*1024)throw Error('待办备份超过1 MB');const backup=JSON.parse(await file.text());await changeTasks(()=>taskStore.restore(backup));message.value='备份已合并，已有待办保持原样'}catch(e){error.value=(e as Error).message}finally{input.value=''}}
async function reminders(e:Event){try{await enableTaskReminders((e.target as HTMLInputElement).checked)}catch(e){error.value=(e as Error).message}}
const timer=setInterval(()=>{now.value=new Date();if(followToday)date.value=beijingDay(now.value)},30000);
onMounted(()=>{void initTasks().catch(()=>{})});onUnmounted(()=>clearInterval(timer));
</script>
<template>
 <section class="campus-agenda" aria-label="统一日程">
  <div class="agenda-heading"><div><h2>日程与待办</h2><p>课程、考试与个人待办 · 北京时间</p></div><button class="primary" :disabled="!tasksReady||tasksBusy" @click="startTask()"><Plus :size="16"/>添加待办</button></div>
  <p v-if="taskError||error" role="alert" class="agenda-note danger">{{error||taskError}} <button v-if="!tasksReady" class="text-button" @click="reloadTasks()">重新读取</button></p><p v-if="message" role="status" class="agenda-note">{{message}}</p>
  <form v-if="editor" class="agenda-editor" aria-label="待办编辑" @submit.prevent="saveTask"><h3>{{editing?'编辑待办':'新增个人待办'}}</h3><label>标题<input v-model="draft.title" aria-label="待办标题" maxlength="100" required placeholder="例如：提交实验报告"/></label><label>关联课程（选填）<input v-model="draft.course" aria-label="关联课程" maxlength="100"/></label><label>截止时间（北京时间，选填）<input v-model="draft.deadline" aria-label="待办截止时间" type="datetime-local"/></label><label>提前提醒<select v-model.number="draft.remindMinutes" aria-label="待办提前提醒" :disabled="!draft.deadline"><option :value="-1">不提醒</option><option :value="0">截止时</option><option :value="5">5分钟前</option><option :value="10">10分钟前</option><option :value="30">30分钟前</option><option :value="60">1小时前</option><option :value="1440">1天前</option></select></label><label>备注<textarea v-model="draft.notes" aria-label="待办备注" maxlength="1000" rows="2"/></label><p class="agenda-caption">个人待办保存在本机；学习平台作业尚未接入。系统提醒需在下方主动开启。</p><div class="agenda-actions"><button type="button" class="secondary" @click="editor=false">取消</button><button class="primary" :disabled="tasksBusy">{{tasksBusy?'保存中…':'保存待办'}}</button></div></form>
  <p v-if="!validDay(date)" class="agenda-note">请选择有效日期，下面暂显示今天的安排。</p>
  <div class="agenda-date"><button class="icon-button" aria-label="前一天日程" @click="moveDay(-1)"><ChevronLeft :size="19"/></button><input v-model="date" type="date" aria-label="日程日期" @change="followToday=false"/><button class="icon-button" aria-label="后一天日程" @click="moveDay(1)"><ChevronRight :size="19"/></button><button class="text-button" @click="today">今天</button></div>
  <div class="agenda-controls"><div class="segmented" aria-label="日程范围"><button :aria-pressed="range===1" @click="range=1">当天</button><button :aria-pressed="range===7" @click="range=7">未来7天</button></div><label><input v-model="showCompleted" type="checkbox"/>显示已完成</label></div>
  <div class="agenda-filters" aria-label="日程类型"><button v-for="[id,label] in [['all','全部'],['course','课程'],['exam','考试'],['task','待办']]" :key="id" :aria-pressed="filter===id" @click="filter=id">{{label}}<small v-if="id==='task'">{{totalTasks}}</small></button></div>
  <p v-if="!academicCache.connected||!schoolTerm?.data" class="agenda-note">学校课程尚未同步；日程仍可显示个人课表与待办。</p><p v-else-if="academicCache.session==='expired'||schoolTerm?.error||academicCache.exams.error" class="agenda-note">学校连接待更新，课程与考试显示上次缓存；个人待办正常保存。</p><p v-if="agenda.unknownExams" class="agenda-note">{{agenda.unknownExams}} 条考试日期未识别，请在考试安排查看原文。</p>
  <section v-if="overdue.length&&(filter==='all'||filter==='task')" class="agenda-overdue"><h3>此前已逾期 <small>{{overdue.length}} 项</small></h3><article v-for="t in overdue" :key="t.id" class="agenda-task-line"><button class="agenda-check" :aria-label="'完成待办 '+t.title" :disabled="tasksBusy" @click="complete(t.id)"><Check :size="15"/></button><button class="agenda-task-copy" @click="startTask(t)"><strong>{{t.title}}</strong><small>{{t.deadline?.replace('T',' ')}} 截止 · {{t.course||'个人待办'}}</small></button><button class="text-button" :aria-label="'删除待办 '+t.title" @click="removeIntent=t.id">删除</button><div v-if="removeIntent===t.id" class="agenda-confirm"><span>删除这项待办？</span><button class="text-button" @click="removeIntent=''">取消</button><button class="text-button danger" @click="removeTask(t.id)">确认删除</button></div></article></section>
  <div v-for="day in days.filter(d=>d.events.length)" :key="day.date" class="agenda-day"><h3>{{dayTitle(day.date)}}<small>{{day.events.length}} 项</small></h3><article v-for="e in day.events" :key="e.id" class="agenda-event" :class="[e.kind,{completed:e.completed}]"><button v-if="e.taskId" class="agenda-check" :aria-label="(e.completed?'恢复待办 ':'完成待办 ')+e.title" :disabled="tasksBusy" @click="complete(e.taskId)"><Check :size="15"/></button><span v-else class="agenda-marker"><CalendarDays v-if="e.kind==='exam'" :size="16"/><Clock3 v-else :size="16"/></span><button class="agenda-event-copy" @click="select(e)"><span class="agenda-event-top"><strong>{{e.title}}</strong><small>{{state(e)}}</small></span><span>{{e.time}}<template v-if="e.location"> · {{e.location}}</template></span><small>{{e.source}}</small></button><button v-if="e.taskId" class="text-button" :aria-label="'删除待办 '+e.title" @click="removeIntent=e.taskId">删除</button><div v-if="removeIntent===e.taskId" class="agenda-confirm"><span>删除这项待办？</span><button class="text-button" @click="removeIntent=''">取消</button><button class="text-button danger" @click="removeTask(e.taskId!)">确认删除</button></div></article></div>
  <p v-if="!visible.length" class="agenda-empty">所选日期暂无已知安排，可添加个人待办。</p>
  <section v-if="undated.length&&(filter==='all'||filter==='task')" class="agenda-day"><h3>未设截止时间<small>{{undated.length}} 项</small></h3><article v-for="t in undated" :key="t.id" class="agenda-task-line" :class="{completed:t.completed}"><button class="agenda-check" :aria-label="(t.completed?'恢复待办 ':'完成待办 ')+t.title" :disabled="tasksBusy" @click="complete(t.id)"><Check :size="15"/></button><button class="agenda-task-copy" @click="startTask(t)"><strong>{{t.title}}</strong><small>{{t.course||'个人待办'}} · {{t.completed?'已完成':'待完成'}}</small></button><button class="text-button" :aria-label="'删除待办 '+t.title" @click="removeIntent=t.id">删除</button><div v-if="removeIntent===t.id" class="agenda-confirm"><span>删除这项待办？</span><button class="text-button" @click="removeIntent=''">取消</button><button class="text-button danger" @click="removeTask(t.id)">确认删除</button></div></article></section>
  <details class="agenda-settings"><summary>提醒与待办备份 <ChevronRight :size="15"/></summary><label class="agenda-notification"><span>开启待办系统提醒<small>{{taskReminderStatus}}</small></span><input type="checkbox" :checked="taskSnapshot.notificationsEnabled" :disabled="!tasksReady||tasksBusy" aria-label="开启待办提醒" @change="reminders"/></label><div class="agenda-backup"><button class="secondary" :disabled="!tasksReady" @click="exportTasks"><FileDown :size="15"/>导出待办备份</button><label class="secondary">恢复待办备份<input type="file" accept=".json,application/json" aria-label="恢复待办备份" @change="restoreFile"/></label></div><p>备份仅包含个人待办。恢复时添加缺失项，保留已有项和当前提醒开关；课程备份仍在「我的」。</p></details>
  <p class="agenda-caption">学校安排来自本人已同步缓存。课程日期按对应学期日历配置，当前配置不代表已验证的官方校历。没有具体时间的考试保留学校原文。</p>
 </section>
</template>
